namespace mdemangler.functiontype;

using mdemangler;

/**
 * This class represents a throw attribute (Microsoft C++ mangling parlance)
 *  of a function within a Microsoft mangled symbol.
 */
public class MDThrowAttribute : MDParsableItem {
	private MDArgumentsList argsList;
	// TODO: consider whether the following two can be consolidated down to one variable
	private bool isNoExcept = false;
	private bool hasThrow = true;

	public MDThrowAttribute(MDMang dmang) : base(dmang)
    {
		argsList = new MDArgumentsList(dmang);
	}

	/* @Override */
	protected void parseInternal()
    {
		if (dmang.peek() == '_' && dmang.peek(1) == 'E') {
			dmang.increment(2);
			isNoExcept = true;
			hasThrow = false;
		}
		else if (dmang.peek() == 'Z') {
			dmang.increment();
			hasThrow = false;
		}
		else {
			argsList.parse();
		}
	}

	/* @Override */
	public void insert(StringBuilder builder) {
		if (isNoExcept) {
			dmang.appendString(builder, "noexcept");
		}
		else if (hasThrow) {
			dmang.appendString(builder, "throw(");
			argsList.insert(builder);
			dmang.appendString(builder, ")");
		}
	}
}

